static struct object * sml_getobj ( struct worker * wrk , struct objcore * oc ) { const struct stevedore * stv ; struct object * o ; CHECK_OBJ_NOTNULL ( wrk , WORKER_MAGIC ) ; CHECK_OBJ_NOTNULL ( oc , OBJCORE_MAGIC ) ; stv = oc -> stobj -> stevedore ; CHECK_OBJ_NOTNULL ( stv , STEVEDORE_MAGIC ) ; if ( stv -> sml_getobj != NULL ) { return ( stv -> sml_getobj ( wrk , oc ) ) ; } CAST_OBJ_NOTNULL ( o , oc -> stobj -> priv , OBJECT_MAGIC ) ; return ( o ) ; } 